glsl1.vert:
precision highp float;
uniform highp mat4 cc_matView;
  uniform highp mat4 cc_matProj;
  uniform highp mat4 cc_matViewProj;
  uniform highp vec4 cc_cameraPos;
#if USE_LOCAL
  uniform highp mat4 cc_matWorld;
#endif
#if SAMPLE_FROM_RT
  #define QUATER_PI         0.78539816340
  #define HALF_PI           1.57079632679
  #define PI                3.14159265359
  #define PI2               6.28318530718
  #define PI4               12.5663706144
  #define INV_QUATER_PI     1.27323954474
  #define INV_HALF_PI       0.63661977237
  #define INV_PI            0.31830988618
  #define INV_PI2           0.15915494309
  #define INV_PI4           0.07957747155
  #define EPSILON           1e-6
  #define EPSILON_LOWP      1e-4
  #define LOG2              1.442695
  #define EXP_VALUE         2.71828183f
  #define FP_MAX            65504.0
  #define FP_SCALE          0.0009765625
  #define FP_SCALE_INV      1024.0
  #define GRAY_VECTOR       vec3(0.299, 0.587, 0.114)
      #define LIGHT_MAP_TYPE_DISABLED 0
  #define LIGHT_MAP_TYPE_ALL_IN_ONE 1
  #define LIGHT_MAP_TYPE_INDIRECT_OCCLUSION 2
  #define REFLECTION_PROBE_TYPE_NONE 0
  #define REFLECTION_PROBE_TYPE_CUBE 1
  #define REFLECTION_PROBE_TYPE_PLANAR 2
  #define LIGHT_TYPE_DIRECTIONAL 0.0
  #define LIGHT_TYPE_POINT 1.0
  #define LIGHT_TYPE_SPOT 2.0
  #define LIGHT_TYPE_SPHERE 3.0
  #define LIGHT_TYPE_RANGED_DIRECTIONAL 4.0
  #define IS_DIRECTIONAL_LIGHT(light_type) (abs(float(light_type) - float(LIGHT_TYPE_DIRECTIONAL)) < EPSILON_LOWP)
  #define IS_SPHERE_LIGHT(light_type) (abs(float(light_type) - float(LIGHT_TYPE_SPHERE)) < EPSILON_LOWP)
  #define IS_SPOT_LIGHT(light_type) (abs(float(light_type) - float(LIGHT_TYPE_SPOT)) < EPSILON_LOWP)
  #define IS_POINT_LIGHT(light_type) (abs(float(light_type) - float(LIGHT_TYPE_POINT)) < EPSILON_LOWP)
  #define IS_RANGED_DIRECTIONAL_LIGHT(light_type) (abs(float(light_type) - float(LIGHT_TYPE_RANGED_DIRECTIONAL)) < EPSILON_LOWP)
#endif
attribute vec3 a_position;
attribute vec2 a_texCoord;
attribute vec4 a_color;
varying vec4 color;
varying vec2 uv0;
vec4 vert () {
  vec4 pos = vec4(a_position, 1);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  #if USE_PIXEL_ALIGNMENT
    pos = cc_matView * pos;
    pos.xyz = floor(pos.xyz);
    pos = cc_matProj * pos;
  #else
    pos = cc_matViewProj * pos;
  #endif
  uv0 = a_texCoord;
  #if SAMPLE_FROM_RT
    uv0 = cc_cameraPos.w > 1.0 ? vec2(uv0.x, 1.0 - uv0.y) : uv0;
  #endif
  color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl1.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture2D(tex, uv).rgb, texture2D(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture2D(tex, uv);
#endif
}
#if USE_ALPHA_TEST
      uniform float alphaThreshold;
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
varying vec4 color;
#if USE_TEXTURE
  varying vec2 uv0;
  uniform sampler2D cc_spriteTexture;
#endif
#if ENABLE_GAUSSIAN_BLUR
                  uniform vec2 textureSize;
  float getWeight(float x, float y) {
    return (1.0 / (2.0 * 3.141592653589793 * pow(1.5, 2.0))) * pow(1.0 / 2.718281828459045, (pow(x, 2.0) + pow(y, 2.0)) / (2.0 * pow(1.5, 2.0)));
  }
#endif
vec4 frag () {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
    o *= CCSampleWithAlphaSeparated(cc_spriteTexture, uv0);
    #if CC_USE_ALPHA_ATLAS_TEXTURE
    o.a *= CCSampleWithAlphaSeparated(cc_spriteTexture, uv0 + vec2(0, 0.5)).r;
    #endif
  #endif
  o *= color;
  ALPHA_TEST(o);
  #if ENABLE_GAUSSIAN_BLUR
    const highp float size = floor(1.5 * 6.0 + 1.0);
    const highp float halfSize = floor(size / 2.0);
    float totalWeight = getWeight(0.0, 0.0);
    for(float x = 1.0; x <= halfSize; x++) {
        totalWeight += getWeight(x, 0.0) * 2.0;
    }
    for(float y = 1.0; y <= halfSize; y++) {
        totalWeight += getWeight(0.0, y) * 2.0;
    }
    for(float x = 1.0; x <= halfSize; x++) {
      for (float y = 1.0; y<= halfSize; y++) {
        totalWeight += getWeight(x, y) * 4.0;
      }
    }
    vec4 finalColor = vec4(0.0, 0.0, 0.0, 0.0);
    float onePxWidth = 1.0 / textureSize.x;
    float onePxHeight = 1.0 / textureSize.y;
    for(float x = -halfSize; x<= halfSize; x++) {
      for (float y = -halfSize; y<= halfSize; y++) {
        float weight = getWeight(x, y) / totalWeight;
        finalColor += CCSampleWithAlphaSeparated(cc_spriteTexture, uv0 + vec2(onePxWidth * x, onePxHeight * y)) * weight;
      }
    }
    o = finalColor;
  #endif
  return o;
}
void main() { gl_FragColor = frag(); }
